def _report_dir_exists(run_uuid) -> bool:
    return os.path.exists(os.path.join(settings.SOMALIER["report_base_dir"], "ancestry", str(run_uuid)))


def _one_batch_per_run(apps, _schema_editor):
    """ The uuid names the report dir on disk, so it moves to the batch unchanged. A run that never got as
        far as somalier (skipped, or failed with no report written) has no report and gets no batch """
    SomalierAncestryRun = apps.get_model("snpdb", "SomalierAncestryRun")
    SomalierAncestryBatch = apps.get_model("snpdb", "SomalierAncestryBatch")

    for run in SomalierAncestryRun.objects.exclude(status__in=["K", "C"]):  # Skipped, Created
        if run.status == "E" and not _report_dir_exists(run.uuid):  # Error
            continue
        run.batch = SomalierAncestryBatch.objects.create(uuid=run.uuid, status=run.status,
                                                         error_exception=run.error_exception)
        run.save(update_fields=["batch"])


def _copy_batch_uuid_to_run(apps, _schema_editor):
    SomalierAncestryRun = apps.get_model("snpdb", "SomalierAncestryRun")
    for run in SomalierAncestryRun.objects.filter(batch__isnull=False).select_related("batch"):
        run.uuid = run.batch.uuid
        run.save(update_fields=["uuid"])


